var currentSelection = (V8.Form && V8.Form.SelectAiApp) ? V8.Form.SelectAiApp : '[]';
V8.OpenAppDialog({
  AppKey: 'microi-platform-service',
  RoutePath: '/app-package-selector',
  Title: '配置 AI 应用包',
  TitleIcon: 'fas fa-box-open',
  Width: 'min(900px, calc(100vw - 64px))',
  OpenType: 'Dialog',
  Data: { SelectAiApp: currentSelection },
  OnSuccess: function (result) {
    var payload = result && result.Data ? result.Data : result;
    if (!payload) return;
    var selectValue = payload.SelectAiApp || JSON.stringify(payload.Selection || []);
    var filesValue = payload.AiAppZipFiles || JSON.stringify(payload.Files || []);
    var manifestValue = payload.AiAppPackageManifest || JSON.stringify(payload.Manifest || []);
    V8.FormSet('SelectAiApp', selectValue);
    V8.FormSet('AiAppZipFiles', filesValue);
    V8.FormSet('AiAppPackageManifest', manifestValue);
    if (V8.Form) {
      V8.Form.SelectAiApp = selectValue;
      V8.Form.AiAppZipFiles = filesValue;
      V8.Form.AiAppPackageManifest = manifestValue;
    }
    V8.Tips('AI应用ZIP包已生成并上传；点击【开始制作】即可写入应用包。', true);
  },
  OnCancel: function () {},
  OnError: function (error) {
    V8.Tips((error && error.message) || 'AI应用包配置器打开失败。', false);
  }
});

var currentData = (V8.Form && V8.Form.SelectData) ? V8.Form.SelectData : '[]';
